import { Initializer } from '@adobe-commerce/elsie/lib';
import { Lang } from '@adobe-commerce/elsie/i18n';
import { events } from '@adobe-commerce/event-bus';
import { state } from '@/requisitionList/lib/state';
import { getStoreConfig } from '@/requisitionList/api/getStoreConfig';

type ConfigProps = {
  langDefinitions?: Lang;
};

export const initialize = new Initializer<ConfigProps>({
  init: async (config) => {
    const defaultConfig = {};

    // set config
    if (!state.config) {
      state.config = await getStoreConfig();
      // Emit event to notify listeners that requisition list has been initialized
      events.emit('requisitionList/initialized', state.config);
    }

    initialize.config.setConfig({ ...defaultConfig, ...config });
  },

  listeners: () => [
    events.on('authenticated', (authenticated) => {
      state.authenticated = authenticated;
      if (!authenticated) {
        state.isCompanyUser = false;
      }
    }),

    events.on(
      'auth/permissions',
      (payload) => {
        // Company users have admin: true (company admin) or at least one
        // Magento_Company::* key. Checking these specifically avoids false
        // positives from B2C-only permissions (e.g. Magento_Sales::place_order).
        state.isCompanyUser =
          payload != null &&
          typeof payload === 'object' &&
          Object.entries(payload).some(
            ([key, value]) =>
              value === true &&
              (key === 'admin' || key.startsWith('Magento_Company::'))
          );
      },
      { eager: true }
    ),
  ],
});

export const config = initialize.config;
