import { RequisitionList } from '@/requisitionList/data/models/requisitionList';

export type StoreConfig = {
  is_requisition_list_active?: string;
  company_enabled?: boolean;
  requisition_list_sharing_enabled?: boolean | string;
  requisition_list_share_max_recipients?: string | number | null;
  requisition_list_share_storefront_path?: string | null;
  [key: string]: any; // Allow additional config properties
};

type State = {
  authenticated: boolean;
  config: StoreConfig | undefined;
  isCompanyUser: boolean;
  requisitionLists: RequisitionList[];
  requisitionListsLoading: boolean;
  requisitionListsVersion: number;
};

const _state: State = (() => {
  return {
    authenticated: false,
    config: undefined,
    isCompanyUser: false,
    requisitionLists: [],
    requisitionListsLoading: false,
    requisitionListsVersion: 0,
  };
})();

// Proxy state to allow reactivity
export const state = new Proxy(_state, {
  set(target, key, value) {
    return Reflect.set(target, key, value);
  },
  get(target, key) {
    return target[key as keyof State];
  },
});

// Helper functions for managing requisition lists
export const setRequisitionLists = (lists: RequisitionList[]) => {
  state.requisitionLists = lists;
  state.requisitionListsVersion++;
};

export const addRequisitionList = (list: RequisitionList) => {
  state.requisitionLists = [...state.requisitionLists, list];
  state.requisitionListsVersion++;
};

export const updateRequisitionList = (list: RequisitionList) => {
  const exists = state.requisitionLists.some(
    (l: RequisitionList) => l.uid === list.uid
  );

  if (exists) {
    state.requisitionLists = state.requisitionLists.map((l: RequisitionList) =>
      l.uid === list.uid ? list : l
    );
  } else {
    state.requisitionLists = [...state.requisitionLists, list];
  }
  state.requisitionListsVersion++;
};

export const getRequisitionListsFromState = () => {
  return state.requisitionLists;
};

export const setRequisitionListsLoading = (loading: boolean) => {
  state.requisitionListsLoading = loading;
};
