import { fetchGraphQl } from '@/requisitionList/api';
import { handleFetchError } from '@/requisitionList/lib/fetch-error';
import { IMPORT_SHARED_REQUISITION_LIST_MUTATION } from '@/requisitionList/api/importSharedRequisitionList/graphql/importSharedRequisitionList';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { transformRequisitionList } from '@/requisitionList/data/transforms';

export interface ImportSharedRequisitionListUserError {
  message: string;
  code: string;
}

export interface ImportSharedRequisitionListResult {
  requisitionList: RequisitionList | null;
  userErrors: ImportSharedRequisitionListUserError[];
}

export const importSharedRequisitionList = async (
  token: string
): Promise<ImportSharedRequisitionListResult> => {
  const { errors, data } = await fetchGraphQl(
    IMPORT_SHARED_REQUISITION_LIST_MUTATION,
    { variables: { token } }
  );

  if (errors) return handleFetchError(errors);

  const result = data?.importSharedRequisitionList;

  return {
    requisitionList: result?.requisition_list
      ? (transformRequisitionList(result.requisition_list) ?? null)
      : null,
    userErrors: (result?.user_errors ?? []).map((e: ImportSharedRequisitionListUserError) => ({
      message: e.message,
      code: e.code,
    })),
  };
};
