import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { fetchGraphQl } from '@/requisitionList/api';
import { MOVE_ITEMS_BETWEEN_REQUISITION_LISTS_MUTATION } from '@/requisitionList/api/moveItemsBetweenRequisitionLists/graphql/moveItemsBetweenRequisitionLists';
import { handleFetchError } from '@/requisitionList/lib/fetch-error';
import { transformRequisitionList } from '@/requisitionList/data/transforms';
import { events } from '@adobe-commerce/event-bus';

export interface MoveItemsResult {
  sourceList: RequisitionList | null;
  destinationList: RequisitionList | null;
}

export const moveItemsBetweenRequisitionLists = async (
  sourceRequisitionListUid: string,
  destinationRequisitionListUid: string,
  requisitionListItemUids: string[],
  pageSize: number,
  currentPage: number
): Promise<MoveItemsResult | null> => {
  const { errors, data } = await fetchGraphQl(
    MOVE_ITEMS_BETWEEN_REQUISITION_LISTS_MUTATION,
    {
      variables: {
        sourceRequisitionListUid,
        destinationRequisitionListUid,
        requisitionListItem: {
          requisitionListItemUids,
        },
        pageSize,
        currentPage,
      },
    }
  );

  if (errors) return handleFetchError(errors);

  if (!data?.moveItemsBetweenRequisitionLists) {
    return null;
  }

  const { source_requisition_list, destination_requisition_list } =
    data.moveItemsBetweenRequisitionLists;

  const sourceList = source_requisition_list
    ? transformRequisitionList(source_requisition_list)
    : null;

  const destinationList = destination_requisition_list
    ? transformRequisitionList(destination_requisition_list)
    : null;

  if (sourceList) {
    events.emit('requisitionList/data', sourceList);
  }

  return { sourceList, destinationList };
};
