import { fetchGraphQl } from '@/requisitionList/api';
import { handleFetchError } from '@/requisitionList/lib/fetch-error';
import { SHARE_REQUISITION_LIST_BY_EMAIL_MUTATION } from '@/requisitionList/api/shareRequisitionListByEmail/graphql/shareRequisitionListByEmail';

export interface ShareRequisitionListByEmailError {
  message: string;
  code: string;
}

export const shareRequisitionListByEmail = async (
  requisitionListUid: string,
  customerUids: string[]
): Promise<Array<ShareRequisitionListByEmailError> | null> => {
  return fetchGraphQl(SHARE_REQUISITION_LIST_BY_EMAIL_MUTATION, {
    variables: { requisitionListUid, customerUids },
  }).then(({ errors, data }) => {
    if (errors) return handleFetchError(errors);

    const shareResult = data?.shareRequisitionListByEmail;

    if ((shareResult?.sent_count ?? 0) > 0) {
      return null;
    }

    if (shareResult?.user_errors?.length) {
      return shareResult.user_errors.map((e: ShareRequisitionListByEmailError) => ({
        message: e.message,
        code: e.code,
      }));
    }
    return [
      { code: 'SHARE_FAILED', message: 'Unable to share requisition list.' },
    ];
  });
};
