import { fetchGraphQl } from '@/requisitionList/api';
import { SHARE_REQUISITION_LIST_BY_TOKEN_MUTATION } from '@/requisitionList/api/shareRequisitionListByToken/graphql/shareRequisitionListByToken';

export interface ShareRequisitionListByTokenResult {
  token: string | null;
  errorMessage: string | null;
}

export const shareRequisitionListByToken = async (
  requisitionListUid: string
): Promise<ShareRequisitionListByTokenResult> => {
  try {
    const { errors, data } = await fetchGraphQl(
      SHARE_REQUISITION_LIST_BY_TOKEN_MUTATION,
      { variables: { requisitionListUid } }
    );

    if (errors?.length) {
      return {
        token: null,
        errorMessage: errors[0]?.message ?? null,
      };
    }

    return {
      token: data?.shareRequisitionListByToken?.token ?? null,
      errorMessage: null,
    };
  } catch (error) {
    return {
      token: null,
      errorMessage:
        error instanceof Error
          ? error.message
          : 'Unable to generate share link.',
    };
  }
};
