import { GET_REQUISITION_LIST_QUERY } from '@/requisitionList/api/getRequisitionList/graphql/getRequisitionList';
import { GET_REQUISITION_LISTS_QUERY } from '@/requisitionList/api/getRequisitionLists/graphql/getRequisitionLists';
import { transformRequisitionList } from '@/requisitionList/data/transforms';
import { fetchGraphQl } from '@/requisitionList/api';
import { handleFetchError } from '@/requisitionList/lib/fetch-error';
import { isValidBase64Uid } from '@/requisitionList/lib/validate-uid';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { Item } from '@/requisitionList/data/models/item';
import { events } from '@adobe-commerce/event-bus';

async function mergeRemainingListItemPages(
  list: RequisitionList,
  listItemsPageSize: number
): Promise<RequisitionList> {
  const pi = list.page_info;
  if (!pi || pi.total_pages <= 1 || pi.current_page >= pi.total_pages) {
    return list;
  }

  const uid = String(list.uid);
  if (!isValidBase64Uid(uid)) {
    return list;
  }

  const mergedItems: Item[] = [...(list.items ?? [])];

  for (let page = pi.current_page + 1; page <= pi.total_pages; page += 1) {
    const { errors, data } = await fetchGraphQl(GET_REQUISITION_LIST_QUERY, {
      variables: {
        requisitionListUid: uid,
        currentPage: page,
        pageSize: listItemsPageSize,
      },
    });

    if (errors) {
      handleFetchError(errors);
    }

    const raw = data?.customer?.requisition_lists?.items?.[0];
    if (!raw) {
      break;
    }

    const chunk = transformRequisitionList(raw);
    if (chunk?.items?.length) {
      mergedItems.push(...chunk.items);
    }
  }

  return {
    ...list,
    items: mergedItems,
    page_info: {
      current_page: 1,
      total_pages: 1,
      page_size: mergedItems.length,
    },
  };
}

export const getRequisitionLists = async (
  currentPage?: number,
  pageSize?: number,
  listItemsPageSize: number = 100
): Promise<RequisitionList[] | null> => {
  const { errors, data } = await fetchGraphQl(GET_REQUISITION_LISTS_QUERY, {
    variables: {
      currentPage,
      pageSize,
      listItemsPageSize,
      listItemsCurrentPage: 1,
    },
  });

  if (errors) return handleFetchError(errors);

  if (!data?.customer?.requisition_lists) {
    return null;
  }

  let reqLists = data.customer.requisition_lists.items.map(
    (requisitionList: any) => transformRequisitionList(requisitionList)
  );

  reqLists = await Promise.all(
    reqLists.map((list) =>
      list == null
        ? Promise.resolve(list)
        : mergeRemainingListItemPages(list, listItemsPageSize)
    )
  );

  events.emit('requisitionLists/data', reqLists);

  return {
    items: reqLists,
    page_info: data.customer?.requisition_lists?.page_info,
    total_count: data.customer?.requisition_lists?.total_count,
  };
};
