import { GET_REQUISITION_LIST_QUERY } from '@/requisitionList/api/getRequisitionList/graphql/getRequisitionList';
import { transformRequisitionList } from '@/requisitionList/data/transforms';
import { fetchGraphQl } from '@/requisitionList/api';
import { handleFetchError } from '@/requisitionList/lib/fetch-error';
import { isValidBase64Uid } from '@/requisitionList/lib/validate-uid';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { Item } from '@/requisitionList/data/models/item';
import { events } from '@adobe-commerce/event-bus';

export const getRequisitionList = async (
  requisitionListID: string,
  currentPage?: number,
  pageSize?: number,
  enrichConfigurableProducts?: (items: Item[]) => Promise<Item[]>
): Promise<RequisitionList | null> => {
  // Validate UID format before making API call
  if (!isValidBase64Uid(requisitionListID)) {
    console.error('Invalid requisition list UID format:', requisitionListID);
    return null;
  }

  const { errors, data } = await fetchGraphQl(GET_REQUISITION_LIST_QUERY, {
    variables: {
      requisitionListUid: requisitionListID,
      currentPage,
      pageSize,
    },
  });

  if (errors) return handleFetchError(errors);

  if (!data?.customer?.requisition_lists?.items?.[0]) {
    return null;
  }

  const rawList = data.customer.requisition_lists.items[0];
  let payload = transformRequisitionList(rawList);
  if (payload?.items?.length && enrichConfigurableProducts) {
    payload = {
      ...payload,
      items: await enrichConfigurableProducts(payload.items),
    };
  }
  events.emit('requisitionList/data', payload);
  return payload;
};
