import { fetchGraphQl } from '@/requisitionList/api';
import { GET_COMPANY_USERS_QUERY } from '@/requisitionList/api/getCompanyUsers/graphql/getCompanyUsers';

export interface CompanyUser {
  id: string;
  firstname: string;
  lastname: string;
  email: string;
}

const PAGE_SIZE = 100;

const fetchPage = async (
  currentPage: number
): Promise<{ items: CompanyUser[]; totalPages: number } | null> => {
  const { errors, data } = await fetchGraphQl(GET_COMPANY_USERS_QUERY, {
    variables: { pageSize: PAGE_SIZE, currentPage },
  });
  if (errors) return null;
  const users = data?.company?.users;
  if (!users?.items?.length) return null;
  return {
    items: users.items,
    totalPages: users.page_info?.total_pages ?? 1,
  };
};

export const getCompanyUsers = async (): Promise<CompanyUser[]> => {
  const firstPage = await fetchPage(1);
  if (!firstPage) return [];

  const { items, totalPages } = firstPage;
  if (totalPages <= 1) return items;

  const remainingPages = await Promise.all(
    Array.from({ length: totalPages - 1 }, (_, i) => fetchPage(i + 2))
  );

  return [
    ...items,
    ...remainingPages.flatMap((page) => page?.items ?? []),
  ];
};
