import { fetchGraphQl } from '@/requisitionList/api';
import { handleFetchError } from '@/requisitionList/lib/fetch-error';
import { GET_SHARED_REQUISITION_LIST_QUERY } from '@/requisitionList/api/getSharedRequisitionList/graphql/getSharedRequisitionList';
import { transformRequisitionList } from '@/requisitionList/data/transforms';
import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { Item } from '@/requisitionList/data/models/item';

export interface SharedRequisitionListResult {
  senderName: string;
  requisitionList: RequisitionList;
}

export const getSharedRequisitionList = async (
  token: string,
  currentPage?: number,
  pageSize?: number,
  enrichConfigurableProducts?: (items: Item[]) => Promise<Item[]>
): Promise<SharedRequisitionListResult | null> => {
  const { errors, data } = await fetchGraphQl(GET_SHARED_REQUISITION_LIST_QUERY, {
    variables: { token, currentPage, pageSize },
  });

  if (errors) return handleFetchError(errors);

  const raw = data?.sharedRequisitionList;
  if (!raw?.requisition_list) {
    return null;
  }

  let requisitionList = transformRequisitionList(raw.requisition_list);
  if (!requisitionList) {
    return null;
  }

  if (requisitionList.items?.length && enrichConfigurableProducts) {
    requisitionList = {
      ...requisitionList,
      items: await enrichConfigurableProducts(requisitionList.items),
    };
  }

  return {
    senderName: raw.sender_name,
    requisitionList,
  };
};
