import { fetchGraphQl } from '@/requisitionList/api';

import { STORE_CONFIG_QUERY } from './graphql/storeConfigQuery';
import { handleFetchError } from '../../lib/fetch-error';
import { StoreConfig } from '@/requisitionList/lib/state';

export const getStoreConfig = async (): Promise<any> => {
  try {
    const { errors, data } = await fetchGraphQl(STORE_CONFIG_QUERY, {
      cache: 'force-cache',
    });

    if (errors) {
      const missingField = errors.some(
        (error) =>
          (error.message &&
            error.message.includes(
              'Cannot query field "is_requisition_list_active"'
            )) ||
          error.message.includes('Cannot query field "company_enabled"')
      );
      if (missingField) {
        return false;
      }
      const missingShareConfig = errors.some((error) =>
        error.message.includes(
          'Cannot query field "requisition_list_sharing_enabled"'
        )
      );
      const missingShareMaxRecipientsConfig = errors.some((error) =>
        error.message.includes(
          'Cannot query field "requisition_list_share_max_recipients"'
        )
      );
      const missingShareStorefrontPathConfig = errors.some((error) =>
        error.message.includes(
          'Cannot query field "requisition_list_share_storefront_path"'
        )
      );

      if (missingShareConfig || missingShareMaxRecipientsConfig || missingShareStorefrontPathConfig) {
        return {
          ...data?.storeConfig,
          ...(missingShareConfig
            ? { requisition_list_sharing_enabled: false }
            : {}),
          ...(missingShareMaxRecipientsConfig
            ? { requisition_list_share_max_recipients: null }
            : {}),
          ...(missingShareStorefrontPathConfig
            ? { requisition_list_share_storefront_path: null }
            : {}),
        } as StoreConfig;
      }
      return handleFetchError(errors);
    }

    return data?.storeConfig;
  } catch {
    return {
      is_requisition_list_active: '0',
      company_enabled: false,
      requisition_list_sharing_enabled: false,
      requisition_list_share_max_recipients: null,
      requisition_list_share_storefront_path: null,
    } as StoreConfig;
  }
};
