import { RequisitionList } from '@/requisitionList/data/models/requisitionList';
import { fetchGraphQl } from '@/requisitionList/api';
import { COPY_ITEMS_BETWEEN_REQUISITION_LISTS_MUTATION } from '@/requisitionList/api/copyItemsBetweenRequisitionLists/graphql/copyItemsBetweenRequisitionLists';
import { handleFetchError } from '@/requisitionList/lib/fetch-error';
import { transformRequisitionList } from '@/requisitionList/data/transforms';

export interface CopyItemsResult {
  destinationList: RequisitionList | null;
}

export const copyItemsBetweenRequisitionLists = async (
  sourceRequisitionListUid: string,
  destinationRequisitionListUid: string,
  requisitionListItemUids: string[]
): Promise<CopyItemsResult | null> => {
  const { errors, data } = await fetchGraphQl(
    COPY_ITEMS_BETWEEN_REQUISITION_LISTS_MUTATION,
    {
      variables: {
        sourceRequisitionListUid,
        destinationRequisitionListUid,
        requisitionListItem: {
          requisitionListItemUids,
        },
      },
    }
  );

  if (errors) return handleFetchError(errors);

  if (!data?.copyItemsBetweenRequisitionLists?.requisition_list) {
    return null;
  }

  const destinationList = transformRequisitionList(
    data.copyItemsBetweenRequisitionLists.requisition_list
  );

  return { destinationList };
};
